-- 23 skutečných míst ověřených 2026-08-06 z oficiálních webů provozovatelů.
-- Spolu se 7 dřívějšími ověřenými záznamy obsahuje čistá databáze 30 míst.
on conflict (id) do update set
  name=excluded.name, category=excluded.category, description=excluded.description, why_visit=excluded.why_visit,
  address=excluded.address, latitude=excluded.latitude, longitude=excluded.longitude,
  opening_hours=excluded.opening_hours, opening_hours_verified_at=excluded.opening_hours_verified_at,
  website_url=excluded.website_url, source_url=excluded.source_url, last_verified_at=excluded.last_verified_at,
  verification_status='verified', status='approved', is_demo=false, university_id=excluded.university_id,
  faculty_id=excluded.faculty_id, price_level=excluded.price_level, student_discount=excluded.student_discount;

update public.places set
  why_visit = coalesce(why_visit, description),
  opening_hours_verified_at = coalesce(opening_hours_verified_at, last_verified_at),
  price_level = coalesce(price_level, case when category in ('library','study_room') then 'free' else 'varies' end)
where status = 'approved' and is_demo = false;
